PREFIX rdf:          <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs:         <http://www.w3.org/2000/01/rdf-schema#>
PREFIX ardoq:        <http://data.ardoq.com/meta-model/>
PREFIX ardoq-common: <http://data.ardoq.com/model/common/>
PREFIX xsd:          <http://www.w3.org/2001/XMLSchema#>
SELECT ?entityId
WHERE {
    ?entity ardoq-common:id ?entityId .
    ?entity (rdf:type / rdfs:subClassOf / rdfs:subClassOf) ardoq:Component .
    ?entity rdf:type ?type244530 .
    ?type244530 rdfs:label "Process" .
    {
        {
            SELECT ?entity (COUNT(?child) AS ?value244531)
            WHERE {
                ?entity (rdf:type / rdfs:subClassOf / rdfs:subClassOf) ardoq:Component .
                OPTIONAL {
                    ?child ardoq-common:parent ?entity .
                }
            }
            GROUP BY ?entity
        }
        FILTER (?value244531 > "0"^^xsd:decimal)
    }
    UNION
    {
        ?entity ?referenceType244532 [] .
        ?referenceType244532 (rdfs:subClassOf / rdfs:subClassOf) ardoq:Reference .
        ?referenceType244532 rdfs:label "Is Supported By" .
    }
    ?entity ?fieldType244534 ?value244533 .
    ?fieldType244534 ardoq-common:name "maturity" .
    FILTER (?value244533 < "3.33"^^xsd:decimal)
}
